/**
 * The CodeMesh brand assets, inlined as data URIs.
 *
 * Embedded rather than served as separate files so the Worker stays a single
 * deployable unit with no asset hosting and no extra request on first paint.
 * Source artwork lives in assets/ and the cream backdrop is keyed out, so both
 * sit cleanly on any surface.
 */

/** Ribbon mark only — favicon, avatar chip, compact placements. */
export const MARK_SRC = "data:image/png;base64,";

/** Full lockup: mark over the wordmark and tagline. */
export const LOCKUP_SRC = "data:image/png;base64,";

export const FAVICON = MARK_SRC;

/** The mark at a given height, for inline use. */
export function mark(size = 32): string {
  return `<img src="${MARK_SRC}" alt="CodeMesh" height="${size}" class="cm-mark">`;
}

/** The full lockup, sized by width. */
export function lockup(width = 150): string {
  return `<img src="${LOCKUP_SRC}" alt="CodeMesh \u2014 Build Together" width="${width}" class="cm-lockup">`;
}
